--
-- Table structure for table `sys_user_scope`
--

DROP TABLE IF EXISTS `sys_user_scope`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_user_scope` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '后台用户主体范围绑定主键',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `scope_type` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'platform' COMMENT '主体范围(platform/tenant/merchant)',
  `platform_id` bigint NOT NULL DEFAULT '1' COMMENT '平台ID',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户ID',
  `merchant_id` bigint NOT NULL DEFAULT '0' COMMENT '商户ID',
  `dept_id` bigint NOT NULL DEFAULT '0' COMMENT '当前主体下的部门ID',
  `role_mode` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '角色模式',
  `activation_status` tinyint NOT NULL DEFAULT '1' COMMENT '激活状态(0:停用,1:激活,2:待激活,3:归档)',
  `is_primary` tinyint NOT NULL DEFAULT '1' COMMENT '是否默认主体(0:否,1:是)',
  `scope_metadata` varchar(1500) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '{}' COMMENT '主体范围元数据(JSON)',
  `created_by` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'admin' COMMENT '创建者',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_by` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '' COMMENT '更新者',
  `updated_at` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_sys_user_scope` (`user_id`,`scope_type`,`platform_id`,`tenant_id`,`merchant_id`),
  KEY `idx_sys_user_scope_lookup` (`scope_type`,`platform_id`,`tenant_id`,`merchant_id`),
  KEY `idx_sys_user_scope_user` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='后台用户主体范围绑定表';
/*!40101 SET character_set_client = @saved_cs_client */;

